use kimo_core::color::{gamut_ray,managed};
#[test]fn ray_bounds_luminance(){let w=managed::luma_weights(0);let mut seed=123u32;for _ in 0..10000{let c=std::array::from_fn(|_|{seed=seed.wrapping_mul(1664525).wrapping_add(1013904223);(seed%4000) as f64/1000.-1.});let y=(0..3).map(|j|w[j]*c[j]).sum::<f64>();let q=gamut_ray::compress(c,w,1.,0.8);assert!(q.iter().all(|v|*v>=-1e-12&&*v<=1.+1e-12));let out=(0..3).map(|j|w[j]*q[j]).sum::<f64>();assert!((out-y.clamp(0.,1.)).abs()<1e-10);}}
#[test]fn ray_neutral_identity(){for v in [0.,0.18,0.5,1.]{let q=gamut_ray::compress([v;3],managed::luma_weights(3),1.,0.8);for x in q{assert!((x-v).abs()<1e-12)}}}
#[test]fn ray_all_gamuts_and_serialized_effect(){use kimo_core::{commands::{Session,dispatch},effects::Frame};use serde_json::json;for g in 0..8{let w=managed::luma_weights(g);for c in [[-0.2,0.4,1.8],[2.,0.1,-0.1],[0.18;3],[-4.;3]]{let q=gamut_ray::compress(c,w,1.,0.8);assert!(q.iter().all(|v|v.is_finite()&&*v>=-1e-10&&*v<=1.+1e-10));}}let mut s=Session::new();let tr=dispatch(&mut s,"add_track",&json!({})).unwrap()["track_id"].clone();let c=dispatch(&mut s,"add_clip",&json!({"track_id":tr,"source_type":"solid","start":0,"duration":1})).unwrap()["clip_id"].clone();dispatch(&mut s,"set_color_pipeline",&json!({"settings":{"enabled":true,"working_gamut":3}})).unwrap();dispatch(&mut s,"add_managed_linear_effect",&json!({"clip_id":c,"kind":"soft_gamut_ray"})).unwrap();let serialized=serde_json::to_string(&s.project).unwrap();let p:kimo_core::model::Project=serde_json::from_str(&serialized).unwrap();let e=&p.find_clip(c.as_str().unwrap()).unwrap().effects[0];let mut f=Frame{w:1,h:1,d:vec![-0.2,0.4,1.8,0.5]};kimo_core::effects::apply(&e.kind,&e.params,&e.strings,&mut f,0.,0).unwrap();assert_eq!(f.d[3],0.5);assert!(f.d[..3].iter().all(|v|*v>=-1e-6&&*v<=1.+1e-6));}
#[test]fn inner_chroma_below_knee_identity(){let w=managed::luma_weights(0);for c in [[0.2,0.3,0.4],[0.18;3],[0.4,0.5,0.6]]{assert_eq!(gamut_ray::compress(c,w,1.,0.8),c)}}
